ProjectALife.DialogueShards["replies_threaten_1"] = {
{"THREATEN","reg=raider|st=neutral,careful",{"Oh, you're gonna kill me? Hah! Okay, tough guy, go on, I'll wait","Say that again, slower, I wanna remember the exact words for when I bury you","You threatening me? ME? Kid, I've done things you haven't even had nightmares about","Big words from somebody holding a stick","Careful, friend, careful... people who say that kind of thing out loud usually don't get to do it","Keep talking, I love it when they get brave right before","Wow... okay... you really want to do this?"}},
{"THREATEN","reg=raider|st=hostile",{"Try it! TRY IT, you son of a bitch!","You wanna die today? Fine! FINE! Come on then!!","Say it one more time and I'll cut your tongue out and nail it to a post","Oh, now you've done it... now you've REALLY done it...","Kill me? You couldn't kill a fly in a jar, {g:pal|lady}!","I'll put you in the ground so deep your grandkids will feel it!"}},
{"THREATEN","reg=raider|st=friendly",{"Whoa, whoa, easy, easy! I thought we were just talking here!","Hey- hey, no need for that, put it down, I wasn't gonna hurt you, I wasn't!"}},
{"THREATEN","reg=gang|st=neutral,careful",{"You threatening me on my own block? Man, you got a death wish","You really don't know who I roll with, do you?","That's cute, say it again so my homeboys hear it","You better mean that, because I do"}},
{"THREATEN","reg=gang|st=hostile",{"Say that to my face, punk, SAY IT AGAIN!","You're DEAD, you hear me? Dead! You just signed it!","Oh word? Oh WORD?! Aight, bet, let's go then!","Nobody talks to me like that! NOBODY!","You said that on my block? You just signed something, {g:man|lady}"}},
{"THREATEN","reg=club|st=neutral,careful",{"{mister}, I've been threatened by better men than you, and they're all buried out back","You make a promise like that, you better be able to keep it","Brothers, you hear this guy? Hah! Somebody write it down"}},
{"THREATEN","reg=club|st=hostile",{"Come on, then! COME ON! I've been waiting for a reason all day!","You touch me and the whole club comes down on you like a landslide","I'll snap you like a twig, old man, just try me"}},
{"THREATEN","reg=crime|st=neutral,careful",{"That was unwise, and I want you to think very carefully about what you say next","Threats are for people who can't make arrangements, are you one of those people?","I'll pretend I didn't hear that, once"}},
{"THREATEN","reg=crime|st=hostile",{"You have no idea what you've just started, none whatsoever","I will make a phone call, and by morning you will not exist, do you understand me?","Nobody says that to me and gets a second conversation - you get this one - use it well"}},
{"THREATEN","reg=prison|st=neutral,careful",{"Whoa, no- please, I don't want trouble, leave me be!","Y-you're gonna kill me? Like they said they would? Like everyone said?","Don't hurt me, don't hurt me, I-- I'll do whatever"}},
{"THREATEN","reg=prison|st=hostile",{"I'll kill you first! You hear me?! I'll kill you first!","Back off! BACK OFF! I've got nothing left to lose, you hear me, NOTHING!","Come near me and I'll bite your damn face off!"}},
{"THREATEN","reg=prison|st=friendly",{"Hey, hey, calm down, I'm not your enemy, I'm NOT!"}},
{"THREATEN","reg=outlaw|st=neutral,careful",{"Mm, big talk, usually the quiet ones are the ones I worry about","You think I haven't heard that before? Out here, everyone says it","Say it again if you mean it, and mean it if you say it again"}},
{"THREATEN","reg=outlaw|st=hostile",{"You're gonna regret that, friend, I promise you that","Wrong guy to threaten, wrong day to try it"}},
{"THREATEN","reg=law|st=neutral,careful",{"Listen, you just threatened a peace officer, and I need you to step back and breathe","That is a criminal threat, and I've written people up for less","I'm going to pretend I didn't hear that, because it's been a long week"}},
{"THREATEN","reg=law|st=hostile",{"That's assault on an officer! Get on the ground, NOW!","You just made the worst decision of your life, hands where I can see them!","You just threatened a sworn officer, on the ground - face down, arms out like an airplane"}},
{"THREATEN","reg=law|st=friendly",{"Whoa, easy there, nobody's gotta get hurt here"}},
{"THREATEN","role=law_sheriff|st=neutral,careful",{"I've been threatened by half this county, {g:son|young lady}, none of them followed through"}},
{"THREATEN","reg=military|st=neutral,careful",{"Civilian, you will stand down immediately, that is your only warning","Threatening military personnel is a federal offense, back away"}},
{"THREATEN","reg=military|st=hostile",{"Stand down NOW or we will use force!"}},
{"THREATEN","reg=military|st=friendly",{"Easy, friend, easy... you're scared, I get it, let's all calm down"}},
{"THREATEN","role=soldier_green|st=neutral,careful",{"P-please don't, I don't want to hurt anybody, please don't make me!"}},
{"THREATEN","role=militia|st=neutral,careful",{"{mister}, I've got a rifle and eleven neighbors who would hear it if I fired","You don't want to be threatening folks on their own land"}},
{"THREATEN","role=militia|st=hostile",{"Come onto my property and make threats? You're gonna be fertilizer!"}},
{"THREATEN","reg=civilian,family,worker,rescue|st=careful",{"Don't, don't, please, I'm no threat"}},
{"THREATEN","reg=law,swat|st=careful",{"That's a mistake, friend"}},
{"THREATEN","reg=military,elite|st=careful",{"Noted"}},
{"THREATEN","reg=outlaw,raider,gang,club,crime,prison|st=careful",{"Careful, kid, threats are a two-way street"}},
{"THREATEN","reg=civilian,family,worker,rescue|tmp=fresh|st=friendly,neutral,careful",{"No no no, don't, don't, please don't!!","Oh God, you're serious, you're SERIOUS, I'll do whatever you want!!","Pleeeease, I have a family, I have a family..","No, no, please, you don't have to, I'll do whatever you say, I'll do anything!!","Oh God, you're going to kill me, aren't you? Please, please, please don't...","Okay!! Okay, I believe you, I believe you, just back up, just back up a little","I'm not fighting you!! Look at me, look at me, do I look like I'm fighting you?!","Don't say that, don't, I haven't done anything, I just wanted to get to my sister's..."}},
{"THREATEN","reg=civilian,family,worker,rescue|tmp=seasoned|st=friendly,neutral,careful",{"Calm down, calm DOWN, I believe you","Easy, I get it, I'm listening","Alright, easy, no need to threaten anybody, I'm listening","You don't scare me as much as you think, but I'll hear you out","Threats, huh? That's how it's going to be? Fine, what do you want?","Jesus, calm down, nobody's fighting you, you're making a scene","You've made your point, you've got a gun, I don't, speak"}},
{"THREATEN","reg=law,swat|st=friendly,neutral,careful",{"Easy.. easy.. let's not do something we'll both regret","Careful, {sir}, threatening an officer's a serious offense","Easy, easy, you don't want to do this, let's step back"}},
{"THREATEN","reg=military,elite|st=friendly,neutral,careful",{"Noted, stand down, stand down","Threat noted, I suggest you stand down"}},
{"THREATEN","reg=outlaw,raider,gang,club,crime,prison|st=friendly,neutral,careful",{"Haha, careful, careful, I'm shaking, can't you tell?"}},
{"THREATEN","reg=civilian,family,worker,rescue|st=hostile",{"Go ahead, kill me, I'm tired of being afraid!","Do it then, do it, I dare you!"}},
{"THREATEN","reg=law,swat|st=hostile",{"Threatening a cop, you're finished"}},
{"THREATEN","reg=military,elite|st=hostile",{"Threat noted, lethal force authorized"}},
{"THREATEN","reg=outlaw,raider,gang,club,crime,prison|st=hostile",{"Threaten me? Hahaha, I'll carve you up for breakfast"}},
{"THREATEN","reg=civilian,family,worker,rescue|tmp=seasoned|st=careful,hostile",{"Do it then, go ahead, or shut your mouth","You'd have to be quicker than you look, friend","Big talk, tough guy, I've heard big talk before"}},
{"THREATEN","reg=family|st=friendly,neutral,careful",{"My goodness, there's no call for that kind of talk, tell me what's wrong"}},
{"THREATEN","reg=law,swat|st=careful,hostile",{"You just threatened an officer, you've got about two seconds to take it back"}},
{"THREATEN","reg=military,elite|st=careful,hostile",{"Say that again and see what happens"}},
{"THREATEN","reg=outlaw,raider,gang,club,crime,prison|st=friendly,neutral",{"Haha, listen to you, such a tough guy, you got anything else?","Careful, now, I've buried better men than you","You're serious? Okay, okay, I'm listening"}},
{"THREATEN","reg=outlaw,raider,gang,club,crime,prison|st=careful,hostile",{"Do it, go on, do it, I'm waiting","Big words, little man, you gonna back them up?","You really want to try me? Please, please, try me"}},
{"THREATEN","tmp=veteran|st=friendly,neutral,careful",{"Understood, and I don't scare easily"}},
{"THREATEN","tmp=predator|st=hostile",{"Heh, say it again, slower, so I can enjoy it"}},
{"THREATEN","st=friendly,neutral",{"That sounded like a threat - think about what you're doing"}},
{"THREATEN","st=careful",{"I'm taking that seriously - don't come closer","I heard you, I'm backing up, and my eyes stay on you the whole way","You'd have to be real sure about that, I don't die easy"}},
{"THREATEN","st=hostile",{"You've made yourself clear, too damn clear","Then do it, you're still talking, which tells me you won't","People who mean it don't announce it"}},
{"THREATEN","reg=civilian,family|tmp=fresh|st=friendly,neutral,careful",{"Why would you say that? I haven't done anything to you!"}},
{"THREATEN","reg=law,swat|st=neutral,careful",{"Watch your hands, I heard the threat"}},
{"THREATEN","reg=military,elite|st=neutral,careful",{"Threat noted - stay back"}},
{"THREATEN","reg=rescue|st=neutral,friendly",{"I'm trying to get through this without anyone else hurt - don't make that harder"}},
{"THREATEN","reg=worker|st=neutral,careful",{"I used to put up with that for a paycheck - not anymore"}},
{"THREATEN","reg=club,gang|st=careful,hostile",{"You rehearsed that, or are you naturally this stupid?"},false,{[1]="GENERIC"}},
{"THREATEN","reg=raider,prison,outlaw,crime|tmp=predator|st=careful,hostile",{"Keep talking, you're doing my thinking for me"}},
{"THREATEN","st=friendly",{"Whoa - whoa, I was just saying hello - where did that come from?","I'm going to pretend you didn't say that, because you look like you haven't slept in a week"},false,{[1]="GENERIC"}},
{"THREATEN","st=neutral",{"Plenty of things out here already want me dead, you'll have to take a number","Then we're both having a bad afternoon, I'd rather not make it worse"}},
{"THREATEN","reg=civilian,family|tmp=fresh|st=careful",{"No! Please! I'm going! I've got a little girl waiting at the Rosewood fire station, please!","I don't have anything! Look, I'm turning my pockets out, look at them!"}},
{"THREATEN","reg=civilian,family|tmp=fresh|st=careful,neutral",{"They got my brother and my mom already - please don't be the one that gets me, okay?"},false,{[1]="GENERIC"}},
{"THREATEN","reg=civilian,family|tmp=fresh|st=neutral",{"Why? I didn't even look at you funny, I didn't do one thing to you!"}},
{"THREATEN","reg=family|tmp=fresh|st=neutral,careful",{"Please don't, I haven't told my kids where I hid the food yet"}},
{"THREATEN","reg=civilian,family|tmp=fresh|st=friendly",{"You don't mean that, you're just scared, I'm scared too, look at my hands"}},
{"THREATEN","reg=civilian,family|tmp=fresh|st=hostile",{"You'll have to catch me first, and I ran the mile for {town} High!"}},
{"THREATEN","reg=family,civilian|tmp=fresh|st=hostile|sex=f",{"Try it! My husband's upstairs with the deer rifle and he's been waiting all week for somebody like you!"}},
{"THREATEN","reg=civilian,family|tmp=fresh|st=hostile,careful|day=0,10",{"The Army's coming any day now, and they'll lock you up for this! You hear me?"},false,{[1]="GENERIC"}},
{"THREATEN","reg=civilian,family,worker|tmp=seasoned|st=neutral,careful",{"I put down my own neighbor on the Tuesday after he turned - threats don't sound like much since"}},
{"THREATEN","reg=civilian,family,worker|tmp=seasoned|st=careful,hostile",{"You've got maybe one good swing before I get mine - think about whether it's worth it"}},
{"THREATEN","role=family_elder|st=neutral,careful",{"I'm seventy-three with a pacemaker, kill me and you'll save the Lord some paperwork"}},
{"THREATEN","reg=worker|st=neutral",{"I've been threatened by a union steward, a loan shark and a bull - only the bull meant it"}},
{"THREATEN","role=rescue_medical|st=careful,neutral",{"I've got the only suture kit between here and West Point - shoot me and you shoot your own stitches"}},
{"THREATEN","role=rescue_clergy|st=neutral,careful",{"If it's my time, it's my time, but son, it isn't your call to make"}},
{"THREATEN","role=rescue_firefighter|st=careful,hostile",{"I walked into a burning Dairy Mart last week, you'll need to be scarier than that"}},
{"THREATEN","reg=law|st=careful",{"Say that again and I'm drawing, that was the last time I ask nice"}},
{"THREATEN","role=law_sheriff,law_sergeant|st=careful,hostile",{"You're the fourth this month to promise me that, I'm still here - hands where I can see them"}},
{"THREATEN","role=law_trooper|st=hostile,careful",{"Kentucky State Police, you just threatened an officer - keep your hands up - slowly"}},
{"THREATEN","role=law_officer,law_deputy|st=neutral",{"{sir}, take that back and walk away, I don't want to write anything up today"}},
{"THREATEN","role=law_corrections|st=careful,neutral",{"I've been threatened by men who'd actually done it, you're not one - I can tell by how you stand"}},
{"THREATEN","reg=law|st=friendly|world=vehicle",{"{g:Buddy|Lady}, I'm the one with the radio and the car - don't do this to yourself"}},
{"THREATEN","reg=swat|st=hostile",{"Threat! Weapons up! Get on the ground now or you will be fired on!"}},
{"THREATEN","role=swat_lead|st=careful",{"Everybody hold, you just talked yourself into four rifles, talk yourself back out"}},
