{"THREATEN","role=soldier|st=careful,neutral",{"Negative, you're not killing anybody today - step back to the wire"}},
{"THREATEN","reg=military|tmp=seasoned|st=neutral",{"Copy your threat, calling it in - want to give me a name for the log?"},false,{[1]="GENERIC"}},
{"THREATEN","role=elite_delta|st=hostile,careful",{"You'd miss - I wouldn't"}},
{"THREATEN","role=elite_operator|st=careful,hostile",{"Threat acknowledged, you have my full attention now, that's bad for you"}},
{"THREATEN","role=mercenary|st=neutral,hostile",{"You couldn't afford what that would cost you"}},
{"THREATEN","role=outlaw|st=neutral,careful",{"I've been shot twice and stabbed once, you'll have to get in line behind a lot of history"}},
{"THREATEN","role=deserter|st=hostile,careful",{"I deserted so nobody could order me to die, you sure as hell can't"}},
{"THREATEN","reg=raider|tmp=predator|st=hostile",{"Hahaha! He's gonna kill me! Dale! Dale, come here, he's gonna kill me!","With that stick? Go on, I'll give you the first swing, then it's my turn"}},
